<?php\ndeclare(strict_types=1);\n\nnamespace Acme\\Validation\\Consolidated;\n\nclass ValidationHelper\n{\n    public static function validateRequired(mixed $value, string $fieldName, array &$errors): bool\n    {\n        if (empty($value)) {\n            $errors[] = \"{$fieldName} is required\";\n            return false;\n        }\n        return true;\n    }\n\n    public static function validateNotBlank(string $value, string $fieldName, array &$errors): bool\n    {\n        if (trim($value) === '') {\n            $errors[] = \"{$fieldName} cannot be blank\";\n            return false;\n        }\n        return true;\n    }\n\n    public static function validateMinLength(string $value, int $min, string $fieldName, array &$errors): bool\n    {\n        if (strlen($value) < $min) {\n            $errors[] = \"{$fieldName} must be at least {$min} characters\";\n            return false;\n        }\n        return true;\n    }\n}\n\nclass UserValidator\n{\n    public function validate(array $data): array\n    {\n        $errors = [];\n        \n        if (!ValidationHelper::validateRequired($data['username'] ?? null, 'username', $errors)) {\n            // consolidated\n        }\n        if (!ValidationHelper::validateRequired($data['email'] ?? null, 'email', $errors)) {\n            // consolidated\n        }\n        if (!ValidationHelper::validateNotBlank($data['username'] ?? '', 'username', $errors)) {\n            // consolidated\n        }\n        \n        return $errors;\n    }\n}
